8	
9	// Aggregates commerce metrics (orders, revenue, commissions) from commission_ledger_entries into daily and hourly analytics tables.
10	class CommerceAnalyticsAggregateService
11	{
12	    use ResolvesTimezone;
13	
14	    /**
15	     * Rebuild all commerce daily aggregates affected by an order.
16	     * Called after ledger entries are created (Shopify order webhook)
17	     * and during hourly compaction.
18	     */
19	    public function rebuildForOrder(string $brandProfessionalId, string $affiliateProfessionalId, string $day): void
20	    {
21	        $this->rebuildProfessionalMetricsDay($affiliateProfessionalId, $day);
22	        $this->rebuildBrandMetricsDay($brandProfessionalId, $day);
23	        $this->rebuildBrandAffiliateDailyDay($brandProfessionalId, $affiliateProfessionalId, $day);
24	        $this->rebuildBrandCommissionDay($brandProfessionalId, $affiliateProfessionalId, $day);
25	    }
26	
27	    /**
28	     * Rebuild both hourly aggregate tables for one brand + affiliate + hour.
29	     * Called immediately after a Shopify order webhook fires so the last-24h view is current.
30	     */
31	    public function rebuildForHour(string $brandProfessionalId, string $affiliateProfessionalId, string $hourStart): void
32	    {
33	        $this->rebuildProfessionalMetricsHour($affiliateProfessionalId, $hourStart);
34	        $this->rebuildBrandMetricsHour($brandProfessionalId, $hourStart);
35	    }
36	
37	    /**
38	     * Rebuild analytics.professional_metrics_hourly for one affiliate + UTC hour.
39	     * Aggregates across ALL brands the affiliate sells for within that hour.
40	     */
41	    public function rebuildProfessionalMetricsHour(string $affiliateProfessionalId, string $hourStart): void
42	    {
43	        $hour = Carbon::parse($hourStart)->utc()->startOfHour();
44	        $hourEnd = $hour->copy()->addHour();
45	        $timezone = $this->professionalTimezone($affiliateProfessionalId);
46	        $now = now();
47	
48	        DB::transaction(function () use ($affiliateProfessionalId, $hour, $hourEnd, $timezone, $now): void {
49	            DB::select('SELECT pg_advisory_xact_lock(hashtext(?))', ["commerce-rebuild:affiliate-hour:{$affiliateProfessionalId}"]);
50	
51	            DB::table('analytics.professional_metrics_hourly')
52	                ->where('affiliate_professional_id', $affiliateProfessionalId)
53	                ->where('hour_start', $hour)
54	                ->delete();
55	
56	            $rows = $this->queryLedger($hour, $hourEnd)
57	                ->where('affiliate_professional_id', $affiliateProfessionalId)
58	                ->groupBy('currency_code')
59	                ->get();
60	
61	            if ($rows->isEmpty()) {
62	                return;
63	            }
64	
65	            $inserts = $rows->map(fn ($row) => [
66	                'hour_start' => $hour,
67	                'affiliate_professional_id' => $affiliateProfessionalId,
68	                'currency_code' => (string) $row->currency_code,
69	                'timezone' => $timezone,
70	                'orders_count' => (int) $row->orders_count,
71	                'gross_cents' => (int) $row->gross_cents,
72	                'refunded_cents' => (int) $row->refunded_cents,
73	                'returned_cents' => 0,
74	                'net_cents' => (int) $row->gross_cents - (int) $row->refunded_cents,
75	                'commission_accrued_cents' => (int) $row->commission_accrued_cents,
76	                'commission_reversed_cents' => (int) $row->commission_reversed_cents,
77	                'commission_paid_cents' => 0, // payouts tracked at daily granularity only
78	                'updated_at' => $now,
79	            ])->all();
80	
81	            DB::table('analytics.professional_metrics_hourly')->insert($inserts);
82	        });
